22: export function createSessionToken(payload: object): string {
23:   const header = Buffer.from(
24:     JSON.stringify({ alg: "HS256", typ: "JWT" })
25:   ).toString("base64url");
26:   const body = Buffer.from(JSON.stringify(payload)).toString("base64url");
27:   const signature = signHS256(`${header}.${body}`, JWT_SECRET);
28:   return `${header}.${body}.${signature}`;
29: }
30: 
31: export function decodeSessionToken(token: string): JWTPayload | null {
32:   try {
33:     const parts = token.split(".");
34:     if (parts.length !== 3) {
35:       return null;
36:     }
37: 
38:     const [header, body, signature] = parts;
39:     const expectedSignature = signHS256(`${header}.${body}`, JWT_SECRET);
40: 
41:     if (signature !== expectedSignature) {
42:       return null;
43:     }
44: 
45:     const payload = JSON.parse(
46:       Buffer.from(body, "base64url").toString("utf-8")
47:     ) as JWTPayload;
48: 
49:     if (payload.exp && payload.exp < Math.floor(Date.now() / 1000)) {
50:       return null;
51:     }
52: 
53:     return payload;
54:   } catch {
55:     return null;
56:   }
57: }
